export const technicalSections = {
  "geometry-theorem": "<section class=\"chapter\" id=\"geometry-theorem\" data-nav=\"results\" data-title=\"Mesh validity\">\n        <div class=\"chapter-inner\">\n          <header class=\"chapter-heading compact-heading\">\n            <div><p class=\"chapter-index\">10 · Proposition 1</p><h2>Mesh validity</h2></div>\n            <p class=\"chapter-statement\">A time-step / Lipschitz condition propagates a valid, positively oriented mesh to the next time level.</p>\n          </header>\n          <article class=\"mesh-update-definition\">\n            <div>\n              <span class=\"formal-label\">General mesh movement</span>\n              <p>Let w<sub>h</sub>:Ω<sup>n−1</sup>→ℝ<sup>d</sup> be a continuous piecewise-affine mesh velocity. Define the mesh-to-mesh map and the nodal update by</p>\n            </div>\n            <div class=\"math-display formula-medium\">\n              <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                <msup><mi>Φ</mi><mi>n</mi></msup><mrow><mo>(</mo><mi>𝐱</mi><mo>)</mo></mrow><mo>:=</mo><mi>𝐱</mi><mo>+</mo><mi>Δ</mi><mi>t</mi><msub><mi>𝐰</mi><mi>h</mi></msub><mrow><mo>(</mo><mi>𝐱</mi><mo>)</mo></mrow><mo>,</mo>\n                <mspace width=\"1.1em\"/><msubsup><mi>𝐏</mi><mi>i</mi><mi>n</mi></msubsup><mo>:=</mo><msup><mi>Φ</mi><mi>n</mi></msup><mrow><mo>(</mo><msubsup><mi>𝐏</mi><mi>i</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>)</mo></mrow><mo>=</mo><msubsup><mi>𝐏</mi><mi>i</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>+</mo><mi>Δ</mi><mi>t</mi><msub><mi>𝐰</mi><mi>h</mi></msub><mrow><mo>(</mo><msubsup><mi>𝐏</mi><mi>i</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>)</mo></mrow><mo>.</mo>\n              </mrow><annotation encoding=\"application/x-tex\">\\Phi^n(x)=x+\\Delta t\\,w_h(x),\\qquad P_i^n=\\Phi^n(P_i^{n-1}).</annotation></semantics></math>\n            </div>\n            <p class=\"formal-note\">The proposition is stated for this general w<sub>h</sub>. The LGMM nodal law in <button class=\"term-link\" type=\"button\" data-term=\"mesh-ode-recall\">Section 6</button> provides one particular mesh velocity.</p>\n          </article>\n          <article class=\"theorem-box readable-theorem\">\n            <header><span>Proposition 1 · no element inversion under a time-step restriction</span><strong>geometry</strong></header>\n            <div class=\"theorem-body\">\n              <p>Let 𝒯<sub>h</sub><sup>n−1</sup> be non-overlapping and non-inverted. For each simplex K∈𝒯<sub>h</sub><sup>n−1</sup>, let <button class=\"term-link\" type=\"button\" data-term=\"element-matrix\">E<sub>K</sub><sup>n−1</sup></button> denote its oriented edge matrix and assume explicitly</p>\n              <div class=\"math-display medium-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>det</mo><mrow><mo>(</mo><msubsup><mi>E</mi><mi>K</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>)</mo></mrow><mo>&gt;</mo><mn>0</mn><mo>,</mo><mspace width=\"1.2em\"/><mo>∀</mo><mi>K</mi><mo>∈</mo><msubsup><mi>𝒯</mi><mi>h</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mi>.</mi></mrow></semantics></math></div>\n              <p>If the mesh-to-mesh deformation satisfies</p>\n              <div class=\"math-display validity-condition\"><span>Δt&nbsp;</span><button class=\"term-link lip-condition-link\" type=\"button\" data-term=\"lip-seminorm\" aria-label=\"Definition of the Lipschitz seminorm\">|w<sub>h</sub>|<sub>Lip, Ω<sup>n−1</sup></sub></button><span>&nbsp;&lt; 1,</span></div>\n              <p>then:</p>\n              <ol>\n                <li>Φ<sup>n</sup> is injective on Ω<sup>n−1</sup>, hence 𝒯<sub>h</sub><sup>n</sup> is non-overlapping.</li>\n                <li>For every K∈𝒯<sub>h</sub><sup>n−1</sup>, the image K<sup>n</sup>=Φ<sup>n</sup>(K) remains positively oriented: det(E<sub>K</sub><sup>n</sup>)&gt;0.</li>\n              </ol><div class=\"validity-visuals\" aria-label=\"Illustrations of the two conclusions\">\n<figure><h4>1 · Global non-overlap</h4><svg viewBox=\"0 0 340 145\" role=\"img\" aria-label=\"Left: two triangles sharing an edge with disjoint interiors; right: two positively oriented triangles with intersecting interiors\"><g font-size=\"12\" text-anchor=\"middle\" fill=\"currentColor\"><text x=\"83\" y=\"15\">Disjoint interiors</text><text x=\"254\" y=\"15\">Intersecting interiors</text></g><g stroke-width=\"1.8\"><polygon points=\"14,112 82,112 66,32\" fill=\"#649ab433\" stroke=\"#5287a2\"/><polygon points=\"82,112 151,78 66,32\" fill=\"#6baaa533\" stroke=\"#408c86\"/><polygon points=\"188,112 265,112 244,32\" fill=\"#649ab444\" stroke=\"#5287a2\"/><polygon points=\"221,101 326,92 268,40\" fill=\"#bc7f8355\" stroke=\"#ad6d75\"/></g><path d=\"M170 20V121\" stroke=\"#c5d6db\"/><g font-size=\"12\" fill=\"currentColor\"><text x=\"48\" y=\"86\">K₁</text><text x=\"103\" y=\"82\">K₂</text><text x=\"218\" y=\"86\">K₁</text><text x=\"282\" y=\"82\">K₂</text></g><g font-size=\"11\" text-anchor=\"middle\"><text x=\"83\" y=\"136\" fill=\"#26776e\">Non-overlapping</text><text x=\"254\" y=\"136\" fill=\"#a14f59\">Overlapping</text></g></svg><figcaption>Distinct element interiors must remain disjoint. The two triangles on the right can both have positive orientation and still overlap.</figcaption></figure>\n<figure><h4>2 · Local positive orientation</h4><svg viewBox=\"0 0 340 145\" role=\"img\" aria-label=\"Counterclockwise ordered vertices yield positive determinant; clockwise ordered vertices yield negative determinant in Cartesian coordinates\"><defs><marker id=\"validity-positive\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3L0 6Z\" fill=\"#398e87\"/></marker><marker id=\"validity-negative\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3L0 6Z\" fill=\"#bb777e\"/></marker></defs><g font-size=\"12\" fill=\"currentColor\" text-anchor=\"middle\"><text x=\"83\" y=\"15\">Positive orientation</text><text x=\"254\" y=\"15\">Inverted orientation</text></g><polygon points=\"26,104 142,104 74,33\" fill=\"#78b4ad26\" stroke=\"#398e87\" stroke-width=\"1.8\"/><path d=\"M42 104H111 M130 91L87 46 M66 45L34 91\" stroke=\"#398e87\" stroke-width=\"2\" fill=\"none\" marker-end=\"url(#validity-positive)\"/><polygon points=\"196,104 312,104 244,33\" fill=\"#bc7f8326\" stroke=\"#bb777e\" stroke-width=\"1.8\"/><path d=\"M204 92L235 46 M256 46L300 91 M297 104H225\" stroke=\"#bb777e\" stroke-width=\"2\" fill=\"none\" marker-end=\"url(#validity-negative)\"/><g font-size=\"12\" fill=\"currentColor\"><text x=\"12\" y=\"120\">P₀</text><text x=\"142\" y=\"120\">P₁</text><text x=\"69\" y=\"28\">P₂</text><text x=\"182\" y=\"120\">P₀</text><text x=\"312\" y=\"120\">P₂</text><text x=\"239\" y=\"28\">P₁</text></g><path d=\"M170 20V121\" stroke=\"#c5d6db\"/><g font-size=\"12\" text-anchor=\"middle\"><text x=\"83\" y=\"137\" fill=\"#26776e\">det Eₖ &gt; 0</text><text x=\"254\" y=\"137\" fill=\"#a14f59\">det Eₖ &lt; 0</text></g></svg><figcaption>For the same vertex ordering, a sign change indicates inversion; zero determinant indicates degeneration. Orientation shown in Cartesian coordinates.</figcaption></figure></div>\n            </div>\n          </article>\n          <div class=\"claim-boundary readable-callout\"><span>Important distinction</span><p><button class=\"term-link\" type=\"button\" data-term=\"non-overlap\">Non-overlap</button> prevents tangling, but it does not imply <button class=\"term-link\" type=\"button\" data-term=\"shape-regularity\">uniform shape regularity</button>. The 2D numerical section shows why this distinction matters.</p></div>\n          <details class=\"math-detail\">\n            <summary><span><b>Simplex setup</b> · element matrix, volume, and abstract update</span><span class=\"detail-action\"><i>Show</i><i>Hide</i></span></summary>\n            <div class=\"detail-content equation-stack\">\n              <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>E</mi><mi>K</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>:=</mo><mo>[</mo><msubsup><mi>P</mi><msub><mi>i</mi><mn>1</mn></msub><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>−</mo><msubsup><mi>P</mi><msub><mi>i</mi><mn>0</mn></msub><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mspace width=\".45em\"/><mi>⋯</mi><mspace width=\".45em\"/><msubsup><mi>P</mi><msub><mi>i</mi><mi>d</mi></msub><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>−</mo><msubsup><mi>P</mi><msub><mi>i</mi><mn>0</mn></msub><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>]</mo><mi>.</mi></mrow></semantics></math></div>\n              <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>vol</mo><mrow><mo>(</mo><msup><mi>K</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msup><mo>)</mo></mrow><mo>=</mo><mfrac><mrow><mo>|</mo><mo>det</mo><mrow><mo>(</mo><msubsup><mi>E</mi><mi>K</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>)</mo></mrow><mo>|</mo></mrow><mrow><mi>d</mi><mi>!</mi></mrow></mfrac><mi>.</mi></mrow></semantics></math></div>\n              <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>𝐏</mi><mi>i</mi><mi>n</mi></msubsup><mo>=</mo><msubsup><mi>𝐏</mi><mi>i</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>+</mo><mi>Δ</mi><mi>t</mi><msub><mi>𝐰</mi><mi>h</mi></msub><mrow><mo>(</mo><msubsup><mi>𝐏</mi><mi>i</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>)</mo></mrow><mo>.</mo></mrow></semantics></math></div>\n              <p>The nodal update is the restriction of Φ<sup>n</sup>(x)=x+Δt w<sub>h</sub>(x) to the vertices of 𝒯<sub>h</sub><sup>n−1</sup>.</p>\n            </div>\n          </details>\n        </div>\n      </section>",
  "mass-stability": "<section class=\"chapter tone-soft\" id=\"mass-stability\" data-nav=\"results\" data-title=\"Mass and stability\">\n        <div class=\"chapter-inner\">\n          <header class=\"chapter-heading\"><div><p class=\"chapter-index\">11 · Corollaries</p><h2>Mass and stability</h2></div><p class=\"chapter-statement\">The mass-preserving and stability properties of the fixed-mesh second-order LG scheme are maintained in the second-order LGMM scheme.</p></header>\n          <div class=\"hypothesis-banner\"><span>Hypothesis 1</span><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>t</mi><mspace width=\"0.167em\"></mspace><msub><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>u</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mrow><mi>C</mi><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msup><mi>W</mi><mrow><mn>1</mn><mo>,</mo><mi>∞</mi></mrow></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow></msub><mo>≤</mo><mfrac><mn>1</mn><mn>8</mn></mfrac><mi>.</mi></mrow></semantics></math></div></div>\n          <div class=\"paired-theorems readable-pair\">\n            <article class=\"theorem-box compact-theorem readable-theorem\">\n              <header><span>Corollary 1 · mass preserving property</span><strong>exact</strong></header>\n              <div class=\"theorem-body\"><p>Under Hypothesis 1, for the second-order LG scheme with a non-inverted moving mesh,</p><div class=\"math-display\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∫</mo><mi>Ω</mi></msub><msubsup><mi>ϕ</mi><mi>h</mi><mi>n</mi></msubsup><mspace width=\"0.167em\"></mspace><mi>d</mi><mi>x</mi><mo>=</mo><msub><mo>∫</mo><mi>Ω</mi></msub><msubsup><mi>ϕ</mi><mi>h</mi><mn>0</mn></msubsup><mspace width=\"0.167em\"></mspace><mi>d</mi><mi>x</mi><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>n</mi><mo>=</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>,</mo><mi>…</mi><mo>,</mo><msub><mi>N</mi><mi>T</mi></msub><mi>.</mi></mrow></semantics></math></div><details class=\"inline-exact\"><summary>Exact statement</summary><p>Suppose that Hypotheses 1 holds true. Let {φ<sub>h</sub><sup>n</sup>}<sub>n=1</sub><sup>N<sub>T</sub></sup> ⊂ Ψ<sub>h</sub> be the solution to second-order Lagrange–Galerkin scheme with a non-inverted moving mesh. Then, it holds that, for n = 0,1,…,N<sub>T</sub>, the identity above is satisfied.</p></details></div>\n            </article>\n            <article class=\"theorem-box compact-theorem readable-theorem\">\n              <header><span>Corollary 2 · stability</span><strong>C independent of h and Δt</strong></header>\n              <div class=\"theorem-body\"><p>Under the same hypotheses, there exists C &gt; 0 independent of h and Δt such that</p><div class=\"math-display\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥</mo><msub><mi>ϕ</mi><mi>h</mi></msub><msub><mo stretchy=\"false\" form=\"postfix\">∥</mo><mrow><msup><mo>ℓ</mo><mi>∞</mi></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msup><mi>L</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow></msub><mo>+</mo><msqrt><mi>ν</mi></msqrt><mspace width=\"0.167em\"></mspace><mo stretchy=\"false\" form=\"postfix\">∥</mo><mi>∇</mi><msub><mi>ϕ</mi><mi>h</mi></msub><msub><mo stretchy=\"false\" form=\"postfix\">∥</mo><mrow><msup><mo>ℓ</mo><mn>2</mn></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msup><mi>L</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow></msub><mo>≤</mo><mi>C</mi><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mo stretchy=\"false\" form=\"postfix\">∥</mo><msubsup><mi>ϕ</mi><mi>h</mi><mn>0</mn></msubsup><mo stretchy=\"false\" form=\"postfix\">∥</mo><mi>+</mi><mo stretchy=\"false\" form=\"postfix\">∥</mo><mi>F</mi><msub><mo stretchy=\"false\" form=\"postfix\">∥</mo><mrow><msup><mo>ℓ</mo><mn>2</mn></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msub><mi>Ψ</mi><mi>h</mi></msub><mi>′</mi><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mi>.</mi></mrow></semantics></math></div><details class=\"inline-exact\"><summary>Exact statement</summary><p>Suppose that Hypotheses 1 holds true. Let {φ<sub>h</sub><sup>n</sup>}<sub>n=1</sub><sup>N<sub>T</sub></sup> ⊂ Ψ<sub>h</sub> be the solution to second-order Lagrange–Galerkin scheme with a non-inverted moving mesh. Then, ∃C &gt; 0 independent of h and Δt such that the stability estimate above holds.</p></details></div>\n            </article>\n          </div>\n          <p class=\"remark-line\"><b>Remark 1.</b> The mass-preserving and stability properties of the second-order Lagrange–Galerkin scheme with fixed mesh (Futai et al., 2022, Theorems 1 and 2) are maintained in the second-order LGMM scheme.</p>\n        </div>\n      </section>",
  "error-1d": "<section class=\"chapter\" id=\"error-1d\" data-nav=\"results\" data-title=\"Published 1D estimate\">\n        <div class=\"chapter-inner\">\n          <header class=\"chapter-heading compact-heading\"><div><p class=\"chapter-index\">12 · Published 1D result</p><h2>Published 1D estimate</h2></div><p class=\"chapter-statement\">The second-order LGMM estimate is O(Δt²+h²) in the ℓ∞(L²) / ℓ²(H¹) energy norm.</p></header>\n          <article class=\"theorem-box error-theorem readable-theorem\">\n            <header><span>Theorem 1 · Error Estimates</span><strong>Putri, K.S. et al. (2024)</strong></header>\n            <div class=\"theorem-body\">\n              <div class=\"hypothesis-inline\"><b>Hypothesis 2.</b><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ϕ</mi><mo>∈</mo><msup><mi>Z</mi><mn>3</mn></msup><mo>∩</mo><msup><mi>H</mi><mn>2</mn></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>0</mn><mo>,</mo><mi>T</mi><mo>;</mo><msup><mi>H</mi><mn>2</mn></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mi>Ω</mi><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>∩</mo><msup><mi>H</mi><mn>1</mn></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>0</mn><mo>,</mo><mi>T</mi><mo>;</mo><msup><mi>H</mi><mn>3</mn></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mi>Ω</mi><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mi>.</mi></mrow></semantics></math></div></div>\n              <p>Suppose that Hypotheses 1 and 2 hold true. Let {φ<sub>h</sub><sup>n</sup>}<sub>n=0</sub><sup>N<sub>T</sub></sup> be the solution to the second-order Lagrange–Galerkin scheme with a non-inverted moving mesh. Then, ∃C &gt; 0 independent of h and Δt such that</p>\n              <div class=\"math-display\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥</mo><msub><mi>ϕ</mi><mi>h</mi></msub><mo>−</mo><mi>ϕ</mi><msub><mo stretchy=\"false\" form=\"postfix\">∥</mo><mrow><msup><mo>ℓ</mo><mi>∞</mi></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msup><mi>L</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow></msub><mo>+</mo><msqrt><mi>ν</mi></msqrt><mspace width=\"0.167em\"></mspace><mo stretchy=\"false\" form=\"postfix\">∥</mo><mi>∇</mi><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msub><mi>ϕ</mi><mi>h</mi></msub><mo>−</mo><mi>ϕ</mi><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><msub><mo stretchy=\"false\" form=\"postfix\">∥</mo><mrow><msup><mo>ℓ</mo><mn>2</mn></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msup><mi>L</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow></msub><mo>≤</mo><mi>C</mi><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mi>Δ</mi><msup><mi>t</mi><mn>2</mn></msup><mo>+</mo><msup><mi>h</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mspace width=\"0.167em\"></mspace><mo stretchy=\"false\" form=\"postfix\">∥</mo><mi>ϕ</mi><msub><mo stretchy=\"false\" form=\"postfix\">∥</mo><mrow><msup><mi>Z</mi><mn>3</mn></msup><mo>∩</mo><msup><mi>H</mi><mn>2</mn></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msup><mi>H</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>∩</mo><msup><mi>H</mi><mn>1</mn></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msup><mi>H</mi><mn>3</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow></msub><mi>.</mi></mrow></semantics></math></div>\n            </div>\n          </article>\n          <div class=\"target-banner\"><span>Multi-D goal</span><strong>Similar O(Δt²+h²) result for multidimensional analysis.</strong></div>\n        </div>\n      </section>",
  "error-equation": "<section class=\"chapter tone-soft\" id=\"error-equation\" data-nav=\"analysis\" data-title=\"Error equation\">\n        <div class=\"chapter-inner\">\n          <header class=\"chapter-heading\">\n            <div><p class=\"chapter-index\">13 · Error estimates</p><h2>Error equation</h2></div>\n            <p class=\"chapter-statement\">Use LG1 to expose the residual structure. The characteristic time-consistency term R₁ is standard; the moving-mesh analysis is concentrated in R₂ and R₃.</p>\n          </header>\n          <article class=\"formal-panel readable-formal wide-formal\">\n            <div class=\"formal-label\">Definitions</div>\n            <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>e</mi><mi>h</mi><mi>n</mi></msubsup><mo>:=</mo><msubsup><mi>ϕ</mi><mi>h</mi><mi>n</mi></msubsup><mo>−</mo><msubsup><mi>P</mi><mi>h</mi><mi>n</mi></msubsup><msup><mi>ϕ</mi><mi>n</mi></msup><mo>,</mo><mspace width=\"1.5em\"/><mi>η</mi><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mo>:=</mo><mi>ϕ</mi><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mo>−</mo><msub><mi>P</mi><mi>h</mi></msub><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mi>ϕ</mi><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mi>.</mi></mrow></semantics></math></div>\n            <p>For every ψ<sub>h</sub>∈Ψ<sub>h</sub><sup>n</sup>, subtraction of the projected continuous equation from the LG1 scheme gives</p>\n            <div class=\"math-display\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mo>(</mo><mfrac><mrow><msubsup><mi>e</mi><mi>h</mi><mi>n</mi></msubsup><mo>−</mo><mrow><mo>(</mo><msubsup><mi>e</mi><mi>h</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msubsup><mo>∘</mo><msubsup><mi>X</mi><mn>1</mn><mi>n</mi></msubsup><mo>)</mo></mrow><msup><mi>γ</mi><mi>n</mi></msup></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mo>+</mo><mi>ν</mi><mrow><mo>(</mo><mi>∇</mi><msubsup><mi>e</mi><mi>h</mi><mi>n</mi></msubsup><mo>,</mo><mi>∇</mi><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mo>=</mo><mo>⟨</mo><msubsup><mi>R</mi><mi>h</mi><mi>n</mi></msubsup><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>⟩</mo><mi>.</mi></mrow></semantics></math></div>\n          </article>\n          <div class=\"residual-cards exact-residuals\">\n            <article><span>R₁ · characteristic time consistency</span><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>R</mi><mn>1</mn><mi>n</mi></msubsup><mo>:=</mo><msub><mi>∂</mi><mi>t</mi></msub><msup><mi>ϕ</mi><mi>n</mi></msup><mo>+</mo><mi>∇</mi><mo>⋅</mo><mrow><mo>(</mo><msup><mi>𝐮</mi><mi>n</mi></msup><msup><mi>ϕ</mi><mi>n</mi></msup><mo>)</mo></mrow><mo>−</mo><mfrac><mrow><msup><mi>ϕ</mi><mi>n</mi></msup><mo>−</mo><mrow><mo>(</mo><msup><mi>ϕ</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msup><mo>∘</mo><msubsup><mi>X</mi><mn>1</mn><mi>n</mi></msubsup><mo>)</mo></mrow><msup><mi>γ</mi><mi>n</mi></msup></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mi>.</mi></mrow></semantics></math></div></article>\n            <article class=\"focus-residual\"><span>R₂ · projection error between moving spaces</span><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>R</mi><mn>2</mn><mi>n</mi></msubsup><mo>:=</mo><mfrac><mrow><msup><mi>η</mi><mi>n</mi></msup><mo>−</mo><mrow><mo>(</mo><msup><mi>η</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msup><mo>∘</mo><msubsup><mi>X</mi><mn>1</mn><mi>n</mi></msubsup><mo>)</mo></mrow><msup><mi>γ</mi><mi>n</mi></msup></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mi>.</mi></mrow></semantics></math></div></article>\n            <article class=\"focus-residual\"><span>R₃ · diffusion acting on the projection error</span><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>⟨</mo><msubsup><mi>R</mi><mn>3</mn><mi>n</mi></msubsup><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>⟩</mo><mo>:=</mo><mi>ν</mi><mrow><mo>(</mo><mi>∇</mi><msup><mi>η</mi><mi>n</mi></msup><mo>,</mo><mi>∇</mi><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mi>.</mi></mrow></semantics></math></div></article>\n          </div>\n          <div class=\"analysis-focus-band\">\n            <button class=\"term-link\" type=\"button\" data-term=\"r1-standard\">R₁ is the standard LG consistency term</button>\n            <p><strong>LG1:</strong> O(Δt). &nbsp; <strong>LG2:</strong> O(Δt²). This estimate is tied to the physical characteristic discretization and is independent of the movement of the finite-element mesh. <strong>Our moving-mesh work therefore focuses on R₂ and R₃.</strong></p>\n          </div>\n          <details class=\"math-detail\"><summary><span><b>Residual sum</b> · exact decomposition</span><span class=\"detail-action\"><i>Show</i><i>Hide</i></span></summary><div class=\"detail-content equation-stack\"><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>R</mi><mi>h</mi><mi>n</mi></msubsup><mo>=</mo><msubsup><mi>R</mi><mn>1</mn><mi>n</mi></msubsup><mo>+</mo><msubsup><mi>R</mi><mn>2</mn><mi>n</mi></msubsup><mo>+</mo><msubsup><mi>R</mi><mn>3</mn><mi>n</mi></msubsup><mi>.</mi></mrow></semantics></math></div></div></details>\n        </div>\n      </section>",
  "projection-strategy": "<section class=\"chapter\" id=\"projection-strategy\" data-nav=\"analysis\" data-title=\"Projection strategy\">\n        <div class=\"chapter-inner\">\n          <header class=\"chapter-heading compact-heading\"><div><p class=\"chapter-index\">14 · Error estimates</p><h2>Projection strategy</h2></div><p class=\"chapter-statement\">Choose an elliptic projection so that R₃ inherits an L²-order estimate; in multiple dimensions the boundary trace must also be compatible with the duality argument.</p></header>\n          <div class=\"projection-layout-clean\">\n            <article class=\"formal-panel readable-formal\"><div class=\"formal-label\">Elliptic projection used for R₃</div><div class=\"math-display\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mrow><mo>(</mo><mi>v</mi><mo>,</mo><mi>z</mi><mo>)</mo></mrow><mo>:=</mo><mrow><mo>(</mo><mi>∇</mi><mi>v</mi><mo>,</mo><mi>∇</mi><mi>z</mi><mo>)</mo></mrow><mo>+</mo><mrow><mo>(</mo><mi>v</mi><mo>,</mo><mi>z</mi><mo>)</mo></mrow><mi>.</mi></mrow></semantics></math></div><p>For each t, define Π<sub>h</sub>(t) by</p><div class=\"math-display\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mrow><mo>(</mo><msub><mi>Π</mi><mi>h</mi></msub><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mi>v</mi><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mo>=</mo><mi>A</mi><mrow><mo>(</mo><mi>v</mi><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mo>,</mo><mspace width=\"1em\"/><mo>∀</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>∈</mo><msub><mi>Ψ</mi><mi>h</mi></msub><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mi>.</mi></mrow></semantics></math></div></article>\n            <article class=\"formal-panel readable-formal\"><div class=\"formal-label\">R₃ estimate</div><p>With η(t)=φ(t)−Π<sub>h</sub>(t)φ(t), orthogonality gives</p><div class=\"math-display\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ν</mi><mrow><mo>(</mo><mi>∇</mi><mi>η</mi><mo>,</mo><mi>∇</mi><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mo>=</mo><mo>−</mo><mi>ν</mi><mrow><mo>(</mo><mi>η</mi><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mi>.</mi></mrow></semantics></math></div><div class=\"math-display projection-long-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>‖</mo><msubsup><mi>R</mi><mn>3</mn><mi>n</mi></msubsup><mo>‖</mo><mo>≤</mo><mi>C</mi><msup><mi>h</mi><mn>2</mn></msup><mo>‖</mo><msup><mi>ϕ</mi><mi>n</mi></msup><msub><mo>‖</mo><mrow><msup><mi>H</mi><mn>2</mn></msup><mrow><mo>(</mo><mi>Ω</mi><mo>)</mo></mrow></mrow></msub><mi>.</mi></mrow></semantics></math></div><p class=\"formal-note\">The exact residual norm is the dual norm used by the stability estimate; the factor ν is absorbed into the constant.</p></article>\n          </div>\n          <div class=\"term-strip\"><button class=\"term-link\" type=\"button\" data-term=\"ritz-projection\">Π<sub>h</sub>(t) · elliptic projection</button><button class=\"term-link\" type=\"button\" data-term=\"elliptic-form\">A(·,·) · projection bilinear form</button><button class=\"term-link\" type=\"button\" data-term=\"r3\">R₃ · diffusion residual</button><button class=\"term-link\" type=\"button\" data-term=\"boundary-l2-projection\">P<sub>h</sub><sup>Γ</sup> · boundary L² projection</button></div>\n\n          <details class=\"math-detail extension-detail\">\n            <summary><span><b>Boundary-compatible elliptic projection</b> · extension used for the multidimensional material-derivative estimate</span><span class=\"detail-action\"><i>Show</i><i>Hide</i></span></summary>\n            <div class=\"detail-content extension-grid\">\n              <article class=\"extension-card\"><h3>Interior orthogonality</h3><p>For the extension estimate, use the same bilinear form A and define</p><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mrow><mo>(</mo><mi>v</mi><mo>,</mo><mi>z</mi><mo>)</mo></mrow><mo>:=</mo><mrow><mo>(</mo><mi>∇</mi><mi>v</mi><mo>,</mo><mi>∇</mi><mi>z</mi><mo>)</mo></mrow><mo>+</mo><mrow><mo>(</mo><mi>v</mi><mo>,</mo><mi>z</mi><mo>)</mo></mrow><mi>.</mi></mrow></semantics></math></div><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mrow><mo>(</mo><msub><mi>Π</mi><mi>h</mi></msub><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mi>ϕ</mi><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mo>=</mo><mi>A</mi><mrow><mo>(</mo><mi>ϕ</mi><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mo>,</mo><mspace width=\"1em\"/><mo>∀</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>∈</mo><msub><mi>V</mi><mrow><mi>h</mi><mo>,</mo><mn>0</mn></mrow></msub><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mi>.</mi></mrow></semantics></math></div></article>\n              <article class=\"extension-card\"><h3>Projected boundary trace</h3><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mo>(</mo><mi>ϕ</mi><mo>−</mo><msubsup><mi>P</mi><mi>h</mi><mi>Γ</mi></msubsup><mi>ϕ</mi><mo>,</mo><msub><mi>μ</mi><mi>h</mi></msub><mo>)</mo></mrow><msub><mspace width=\".1em\"/><mi>Γ</mi></msub><mo>=</mo><mn>0</mn><mo>,</mo><mspace width=\"1em\"/><mo>∀</mo><msub><mi>μ</mi><mi>h</mi></msub><mo>∈</mo><msub><mi>Λ</mi><mi>h</mi></msub><mi>,</mi></mrow></semantics></math></div><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Π</mi><mi>h</mi></msub><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mi>ϕ</mi><msub><mo>|</mo><mi>Γ</mi></msub><mo>=</mo><msubsup><mi>P</mi><mi>h</mi><mi>Γ</mi></msubsup><mrow><mo>(</mo><mi>ϕ</mi><msub><mo>|</mo><mi>Γ</mi></msub><mo>)</mo></mrow><mi>.</mi></mrow></semantics></math></div></article>\n              <article class=\"extension-card key-card\"><h3>Key boundary gain</h3><div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>‖</mo><mi>ϕ</mi><mo>−</mo><msubsup><mi>P</mi><mi>h</mi><mi>Γ</mi></msubsup><mi>ϕ</mi><msub><mo>‖</mo><mrow><msup><mi>H</mi><mrow><mo>−</mo><mn>1</mn><mo>/</mo><mn>2</mn></mrow></msup><mrow><mo>(</mo><mi>Γ</mi><mo>)</mo></mrow></mrow></msub><mo>≤</mo><mi>C</mi><msup><mi>h</mi><mn>2</mn></msup><mo>‖</mo><mi>ϕ</mi><msub><mo>‖</mo><mrow><msup><mi>H</mi><mn>2</mn></msup><mrow><mo>(</mo><mi>Ω</mi><mo>)</mo></mrow></mrow></msub><mi>.</mi></mrow></semantics></math></div><p>The L²(Γ) orthogonality supplies the additional h<sup>1/2</sup> needed in the boundary duality term.</p></article>\n            </div>\n          </details>\n        </div>\n      </section>",
  "r2-analysis": "<section class=\"chapter tone-soft\" id=\"r2-analysis\" data-nav=\"analysis\" data-title=\"R2 and material derivative\">\n        <div class=\"chapter-inner\">\n          <header class=\"chapter-heading\">\n            <div><p class=\"chapter-index\">15 · Error estimates</p><h2>R₂: discrete residual → material derivative</h2></div>\n            <p class=\"chapter-statement\">R₂ compares projection errors that live on different moving spaces. Insert the mesh map Y, split the comparison into four exact differences, then estimate the only genuinely moving-projection term through a material derivative.</p>\n          </header>\n\n          <article class=\"formal-panel readable-formal wide-formal r2-exact-panel\">\n            <div class=\"formal-label\">Start from the exact conservative residual</div>\n            <div class=\"math-display medium-math\">\n              <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                <msubsup><mi>R</mi><mn>2</mn><mi>n</mi></msubsup><mo>=</mo>\n                <mfrac><mrow><msup><mi>η</mi><mi>n</mi></msup><mo>−</mo><mrow><mo>(</mo><msup><mi>η</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msup><mo>∘</mo><msubsup><mi>X</mi><mn>1</mn><mi>n</mi></msubsup><mo>)</mo></mrow><msup><mi>γ</mi><mi>n</mi></msup></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mi>.</mi>\n              </mrow><annotation encoding=\"application/x-tex\">R_2^n=\\frac{\\eta^n-(\\eta^{n-1}\\circ X_1^n)\\gamma^n}{\\Delta t}.</annotation></semantics></math>\n            </div>\n            <p><button class=\"term-link inline-term\" type=\"button\" data-term=\"r2-residual\">R<sub>2</sub><sup>n</sup></button> is the projection-error residual, with η(t)=φ(t)−Π<sub>h</sub>(t)φ(t). The physical map X<sub>1</sub><sup>n</sup> and its Jacobian γ<sup>n</sup> belong to the conservative LG step. To compare η<sup>n</sup> and η<sup>n−1</sup> on the moving finite-element spaces, introduce the backward mesh flow.</p>\n            <div class=\"mesh-flow-definition\">\n              <button class=\"term-link\" type=\"button\" data-term=\"mesh-flow\">mesh-transport map Y</button>\n              <div class=\"math-display compact-math\">\n                <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                  <mfrac><mrow><mi>d</mi><mi>Y</mi></mrow><mrow><mi>d</mi><mi>t</mi></mrow></mfrac><mrow><mo>(</mo><mi>t</mi><mo>;</mo><mi>x</mi><mo>,</mo><msup><mi>t</mi><mi>n</mi></msup><mo>)</mo></mrow><mo>=</mo><msub><mi>𝐰</mi><mi>h</mi></msub><mrow><mo>(</mo><mi>Y</mi><mrow><mo>(</mo><mi>t</mi><mo>;</mo><mi>x</mi><mo>,</mo><msup><mi>t</mi><mi>n</mi></msup><mo>)</mo></mrow><mo>,</mo><mi>t</mi><mo>)</mo></mrow><mo>,</mo>\n                  <mspace width=\"1em\"/><mi>Y</mi><mrow><mo>(</mo><msup><mi>t</mi><mi>n</mi></msup><mo>;</mo><mi>x</mi><mo>,</mo><msup><mi>t</mi><mi>n</mi></msup><mo>)</mo></mrow><mo>=</mo><mi>x</mi><mi>.</mi>\n                </mrow><annotation encoding=\"application/x-tex\">\\frac{dY}{dt}(t;x,t^n)=\\mathbf w_h(Y(t;x,t^n),t),\\qquad Y(t^n;x,t^n)=x.</annotation></semantics></math>\n              </div>\n              <p>Set Y<sub>1</sub><sup>n</sup>(x):=Y(t<sup>n−1</sup>;x,t<sup>n</sup>). For a frozen first-order mesh velocity, Y<sub>1</sub><sup>n</sup>(x)≈x−Δt w<sub>h</sub><sup>n</sup>(x), which is the map used in the hand derivation.</p>\n            </div>\n            <div class=\"mapping-visual-panel\">\n              <div class=\"mapping-visual-copy\">\n                <span class=\"section-kicker\">Line movement</span>\n                <h3>How the backward mesh flow Y connects the moving spaces</h3>\n                <p>To compare quantities in different moving spaces, follow the <strong>mesh trajectory</strong> rather than the physical characteristic. On one time step with frozen velocity, the hand derivation uses</p>\n                <div class=\"formula-display formula-compact html-math\">Y(t;x,t<sup>n</sup>) := x - (t<sup>n</sup>-t) w<sub>h</sub><sup>n</sup>(x), &nbsp; Y<sub>1</sub><sup>n</sup>(x)=Y(t<sup>n-1</sup>;x,t<sup>n</sup>).</div>\n                <p>Along this line movement, the transported P1 basis is unchanged:</p>\n                <div class=\"formula-display formula-compact html-math\"><span class=\"frac\"><span class=\"top\">d</span><span class=\"bottom\">dt</span></span> φ<sub>i</sub>(Y(t),t)=0, &nbsp; i=1,…,N<sub>P</sub>.</div>\n              </div>\n              <figure class=\"mapping-illustration\">\n                <svg viewBox=\"0 0 860 390\" aria-label=\"Backward mesh-flow illustration across three time levels\">\n                  <line x1=\"90\" y1=\"70\" x2=\"640\" y2=\"70\" class=\"map-level top\"/>\n                  <line x1=\"90\" y1=\"205\" x2=\"640\" y2=\"205\" class=\"map-level mid\"/>\n                  <line x1=\"90\" y1=\"340\" x2=\"640\" y2=\"340\" class=\"map-level bot\"/>\n                  <text x=\"48\" y=\"76\" class=\"map-time-label\">t<tspan dy=\"-8\" font-size=\"12\">n</tspan></text>\n                  <text x=\"66\" y=\"211\" class=\"map-time-label\">t</text>\n                  <text x=\"26\" y=\"346\" class=\"map-time-label\">t<tspan dy=\"-8\" font-size=\"12\">n−1</tspan></text>\n                  <text x=\"680\" y=\"76\" class=\"map-domain-label\">Ω<tspan dy=\"-8\" font-size=\"12\">n</tspan></text>\n                  <text x=\"680\" y=\"211\" class=\"map-domain-label\">Ω(t)</text>\n                  <text x=\"680\" y=\"346\" class=\"map-domain-label\">Ω<tspan dy=\"-8\" font-size=\"12\">n−1</tspan></text>\n\n                  <circle cx=\"515\" cy=\"70\" r=\"7\" class=\"map-point current\"/>\n                  <text x=\"530\" y=\"60\" class=\"map-point-label current\">x</text>\n\n                  <circle cx=\"455\" cy=\"205\" r=\"6.5\" class=\"map-point mesh\"/>\n                  <text x=\"471\" y=\"193\" class=\"map-point-label mesh\">Y(t;x,t<tspan dy=\"-8\" font-size=\"11\">n</tspan>)</text>\n\n                  <circle cx=\"395\" cy=\"340\" r=\"6.5\" class=\"map-point mesh\"/>\n                  <text x=\"412\" y=\"330\" class=\"map-point-label mesh\">Y<tspan dy=\"-8\" font-size=\"11\">1</tspan><tspan dy=\"8\" font-size=\"15\">n</tspan>(x)</text>\n\n                  <path d=\"M 515 70 L 395 340\" class=\"map-curve mesh-curve\"/>\n                  <path d=\"M 305 340 L 332 205 L 358 70\" class=\"map-curve node-curve\"/>\n                  <circle cx=\"305\" cy=\"340\" r=\"5.5\" class=\"map-point node\"/>\n                  <circle cx=\"332\" cy=\"205\" r=\"5.5\" class=\"map-point node\"/>\n                  <circle cx=\"358\" cy=\"70\" r=\"5.5\" class=\"map-point node\"/>\n                  <text x=\"265\" y=\"358\" class=\"map-node-label\">P<tspan dy=\"-8\" font-size=\"11\">i</tspan><tspan dy=\"8\" font-size=\"15\">n−1</tspan></text>\n                  <text x=\"338\" y=\"62\" class=\"map-node-label\">P<tspan dy=\"-8\" font-size=\"11\">i</tspan><tspan dy=\"8\" font-size=\"15\">n</tspan></text>\n\n                </svg>\n                <div class=\"map-transport-note\">\n                  <span>Transported P1 basis</span>\n                  <p>Fixed nodal coefficients + transported basis imply that ψ<sub>h</sub> is constant along Y:</p>\n                  <strong><span class=\"mdot\">ψ</span><sub>h</sub> = 0.</strong>\n                </div>\n                <figcaption>The orange straight line is the frozen-velocity backward map Y. It connects the moving finite-element spaces Ψ<sub>h</sub>(t<sup>n</sup>), Ψ<sub>h</sub>(t), and Ψ<sub>h</sub>(t<sup>n−1</sup>).</figcaption>\n              </figure>\n            </div>\n          </article>\n\n          <div class=\"r2-split-heading\"><span>Insert Y<sub>1</sub><sup>n</sup> and add–subtract three intermediate values</span><strong>Four differences reconstruct R<sub>2</sub><sup>n</sup> exactly.</strong></div>\n          <div class=\"r2-term-grid\">\n            <article class=\"r2-term primary-r2-term\">\n              <button class=\"q-term-link\" type=\"button\" data-term=\"q-mov\">A · Q<sub>mov</sub><sup>n</sup> · moving projection</button>\n              <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                <msubsup><mi>Q</mi><mi>mov</mi><mi>n</mi></msubsup><mo>:=</mo><mfrac><mrow><msup><mi>η</mi><mi>n</mi></msup><mo>−</mo><msup><mi>η</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msup><mo>∘</mo><msubsup><mi>Y</mi><mn>1</mn><mi>n</mi></msubsup></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mi>.</mi>\n              </mrow></semantics></math></div>\n              <p>Time-dependent projection error followed along the mesh trajectory.</p>\n            </article>\n            <article class=\"r2-term mesh-r2-term\">\n              <button class=\"q-term-link\" type=\"button\" data-term=\"q-mesh\">B · Q<sub>mesh</sub><sup>n</sup> · mesh displacement</button>\n              <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                <msubsup><mi>Q</mi><mi>mesh</mi><mi>n</mi></msubsup><mo>:=</mo><mfrac><mrow><msup><mi>η</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msup><mo>∘</mo><msubsup><mi>Y</mi><mn>1</mn><mi>n</mi></msubsup><mo>−</mo><msup><mi>η</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msup></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mi>.</mi>\n              </mrow></semantics></math></div>\n              <p>Difference produced by the mesh map itself.</p>\n            </article>\n            <article class=\"r2-term phys-r2-term\">\n              <button class=\"q-term-link\" type=\"button\" data-term=\"q-phys\">C · Q<sub>phys</sub><sup>n</sup> · physical characteristic</button>\n              <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                <msubsup><mi>Q</mi><mi>phys</mi><mi>n</mi></msubsup><mo>:=</mo><mfrac><mrow><msup><mi>η</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msup><mo>−</mo><msup><mi>η</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msup><mo>∘</mo><msubsup><mi>X</mi><mn>1</mn><mi>n</mi></msubsup></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mi>.</mi>\n              </mrow></semantics></math></div>\n              <p>Bridge between mesh transport and physical transport.</p>\n            </article>\n            <article class=\"r2-term jac-r2-term\">\n              <button class=\"q-term-link\" type=\"button\" data-term=\"q-jacobian\">D · Q<sub>J</sub><sup>n</sup> · conservative Jacobian</button>\n              <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                <msubsup><mi>Q</mi><mi>J</mi><mi>n</mi></msubsup><mo>:=</mo><mfrac><mrow><mrow><mo>(</mo><msup><mi>η</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msup><mo>∘</mo><msubsup><mi>X</mi><mn>1</mn><mi>n</mi></msubsup><mo>)</mo></mrow><mrow><mo>(</mo><mn>1</mn><mo>−</mo><msup><mi>γ</mi><mi>n</mi></msup><mo>)</mo></mrow></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mi>.</mi>\n              </mrow></semantics></math></div>\n              <p>Volume-change correction from the conservative pullback.</p>\n            </article>\n          </div>\n          <div class=\"r2-sum-line\">\n            <div class=\"r2-identity-copy\">\n              <span>Exact identity</span>\n              <small>No approximation has been made in this split.</small>\n            </div>\n            <div class=\"r2-identity-math\" aria-label=\"R two n equals Q moving n plus Q mesh n plus Q physical n plus Q J n\">\n              <strong>R<sub>2</sub><sup>n</sup></strong><b>=</b>\n              <button class=\"identity-token token-mov\" type=\"button\" data-term=\"q-mov\">Q<sub>mov</sub><sup>n</sup></button><b>+</b>\n              <button class=\"identity-token token-mesh\" type=\"button\" data-term=\"q-mesh\">Q<sub>mesh</sub><sup>n</sup></button><b>+</b>\n              <button class=\"identity-token token-phys\" type=\"button\" data-term=\"q-phys\">Q<sub>phys</sub><sup>n</sup></button><b>+</b>\n              <button class=\"identity-token token-jac\" type=\"button\" data-term=\"q-jacobian\">Q<sub>J</sub><sup>n</sup></button>\n            </div>\n          </div>\n\n          <details class=\"r2-reconstruction\" id=\"r2Reconstruction\">\n            <summary>\n              <span><b>Why does this sum become R<sub>2</sub><sup>n</sup>?</b> · reveal the telescoping cancellation</span>\n              <span class=\"detail-action\"><i>Show</i><i>Hide</i></span>\n            </summary>\n            <div class=\"r2-reconstruction-body\">\n              <div class=\"r2-algebra-steps\" role=\"tablist\" aria-label=\"Simplify the Q terms step by step\">\n                <button class=\"active\" type=\"button\" role=\"tab\" aria-selected=\"true\" data-r2-step=\"0\"><span>1</span>Substitute</button>\n                <button type=\"button\" role=\"tab\" aria-selected=\"false\" data-r2-step=\"1\"><span>2</span>Cancel</button>\n                <button type=\"button\" role=\"tab\" aria-selected=\"false\" data-r2-step=\"2\"><span>3</span>Expand</button>\n                <button type=\"button\" role=\"tab\" aria-selected=\"false\" data-r2-step=\"3\"><span>4</span>Recover R<sub>2</sub><sup>n</sup></button>\n              </div>\n\n              <div class=\"r2-algebra-frame\" aria-live=\"polite\">\n                <section class=\"r2-algebra-stage active\" data-r2-step-panel=\"0\">\n                  <span class=\"algebra-caption\">Substitute the four definitions into their sum.</span>\n                  <div class=\"telescoping-formula html-math\">\n                    <strong>Q<sub>mov</sub><sup>n</sup>+Q<sub>mesh</sub><sup>n</sup>+Q<sub>phys</sub><sup>n</sup>+Q<sub>J</sub><sup>n</sup></strong>\n                    <b>=</b>\n                    <span class=\"large-frac\"><span class=\"top\">η<sup>n</sup> − <em class=\"cancel-y\">η<sup>n−1</sup>∘Y<sub>1</sub><sup>n</sup></em> + <em class=\"cancel-y\">η<sup>n−1</sup>∘Y<sub>1</sub><sup>n</sup></em> − <em class=\"cancel-prev\">η<sup>n−1</sup></em> + <em class=\"cancel-prev\">η<sup>n−1</sup></em> − <em class=\"cancel-x\">η<sup>n−1</sup>∘X<sub>1</sub><sup>n</sup></em> + <em class=\"jac-group\">(η<sup>n−1</sup>∘X<sub>1</sub><sup>n</sup>)(1−γ<sup>n</sup>)</em></span><span class=\"bottom\">Δt</span></span>\n                  </div>\n                </section>\n\n                <section class=\"r2-algebra-stage\" data-r2-step-panel=\"1\" hidden>\n                  <span class=\"algebra-caption\">The inserted mesh value and the plain previous-time value occur once with each sign.</span>\n                  <div class=\"telescoping-formula html-math\">\n                    <strong>Q<sub>mov</sub><sup>n</sup>+Q<sub>mesh</sub><sup>n</sup>+Q<sub>phys</sub><sup>n</sup>+Q<sub>J</sub><sup>n</sup></strong><b>=</b>\n                    <span class=\"large-frac\"><span class=\"top\">η<sup>n</sup> − <em class=\"cancel-y is-cancelled\">η<sup>n−1</sup>∘Y<sub>1</sub><sup>n</sup></em> + <em class=\"cancel-y is-cancelled\">η<sup>n−1</sup>∘Y<sub>1</sub><sup>n</sup></em> − <em class=\"cancel-prev is-cancelled\">η<sup>n−1</sup></em> + <em class=\"cancel-prev is-cancelled\">η<sup>n−1</sup></em> − <em class=\"cancel-x\">η<sup>n−1</sup>∘X<sub>1</sub><sup>n</sup></em> + <em class=\"jac-group\">(η<sup>n−1</sup>∘X<sub>1</sub><sup>n</sup>)(1−γ<sup>n</sup>)</em></span><span class=\"bottom\">Δt</span></span>\n                  </div>\n                  <p class=\"algebra-note\">The Y-dependent terms cancel, as do −η<sup>n−1</sup> and +η<sup>n−1</sup>.</p>\n                </section>\n\n                <section class=\"r2-algebra-stage\" data-r2-step-panel=\"2\" hidden>\n                  <span class=\"algebra-caption\">Expand the conservative Jacobian factor.</span>\n                  <div class=\"telescoping-formula html-math\">\n                    <strong>Q<sub>mov</sub><sup>n</sup>+Q<sub>mesh</sub><sup>n</sup>+Q<sub>phys</sub><sup>n</sup>+Q<sub>J</sub><sup>n</sup></strong><b>=</b>\n                    <span class=\"large-frac\"><span class=\"top\">η<sup>n</sup> − <em class=\"cancel-x is-cancelled\">η<sup>n−1</sup>∘X<sub>1</sub><sup>n</sup></em> + <em class=\"cancel-x is-cancelled\">η<sup>n−1</sup>∘X<sub>1</sub><sup>n</sup></em> − <em class=\"final-pullback\">(η<sup>n−1</sup>∘X<sub>1</sub><sup>n</sup>)γ<sup>n</sup></em></span><span class=\"bottom\">Δt</span></span>\n                  </div>\n                  <p class=\"algebra-note\">The remaining characteristic value also cancels before the Jacobian-weighted pullback.</p>\n                </section>\n\n                <section class=\"r2-algebra-stage r2-recovered-stage\" data-r2-step-panel=\"3\" hidden>\n                  <span class=\"algebra-caption\">What remains is exactly the original conservative residual.</span>\n                  <div class=\"telescoping-formula html-math recovered-formula\">\n                    <strong>Q<sub>mov</sub><sup>n</sup>+Q<sub>mesh</sub><sup>n</sup>+Q<sub>phys</sub><sup>n</sup>+Q<sub>J</sub><sup>n</sup></strong><b>=</b>\n                    <span class=\"large-frac\"><span class=\"top\">η<sup>n</sup> − (η<sup>n−1</sup>∘X<sub>1</sub><sup>n</sup>)γ<sup>n</sup></span><span class=\"bottom\">Δt</span></span>\n                    <b>=</b><strong class=\"recovered-r2\">R<sub>2</sub><sup>n</sup></strong>\n                  </div>\n                </section>\n              </div>\n            </div>\n          </details>\n\n          <article class=\"material-bridge-panel\">\n            <div class=\"material-bridge-head\"><span>Key reduction</span><strong>Estimate Q<sub>mov</sub><sup>n</sup> through a material-derivative norm</strong></div>\n            <div class=\"material-definition-row\">\n              <div>\n                <span class=\"small-label\">mesh material derivative</span>\n                <div class=\"formula-display formula-medium html-math\"><span class=\"mdot\">v</span> := ∂<sub>t</sub>v + <b>w</b><sub>h</sub> · ∇v.</div>\n                <button class=\"term-link\" type=\"button\" data-term=\"material-derivative\">dot notation · derivative along the mesh velocity</button>\n              </div>\n              <div class=\"bridge-arrow\" aria-hidden=\"true\">⇒</div>\n              <div>\n                <span class=\"small-label\">one-step bound</span>\n                <div class=\"formula-display formula-compact html-math norm-formula\">‖Q<sub>mov</sub><sup>n</sup>‖<sub>L<sup>2</sup>(Ω)</sub> ≤ <span class=\"frac\"><span class=\"top\">C</span><span class=\"bottom\">√Δt</span></span> ‖<span class=\"mdot\">η</span>‖<sub>L<sup>2</sup>(t<sup>n-1</sup>, t<sup>n</sup>; L<sup>2</sup>(Ω))</sub>.</div>\n              </div>\n            </div>\n            <div class=\"strategy-shift\">\n              <span>Strategy shift</span>\n              <p>Instead of attacking the discrete quotient directly, shift the problem to a sharp estimate for <strong>‖<span class=\"mdot\">η</span>‖</strong>. The remaining Q<sub>mesh</sub>, Q<sub>phys</sub>, and Q<sub>J</sub> terms are then handled with the static projection estimates and the mesh / characteristic mapping estimates.</p>\n            </div>\n            <button class=\"derivation-reveal\" id=\"qmovDerivationButton\" type=\"button\" aria-controls=\"qmovDerivation\" aria-expanded=\"false\">\n              <span>Why does the discrete quotient lead to ‖<span class=\"mdot\">η</span>‖?</span>\n              <strong>Show derivation</strong>\n            </button>\n          </article>\n\n          <details class=\"math-detail extension-detail\" id=\"qmovDerivation\">\n            <summary><span><b>Derivation of the mesh-transport bound</b> · chain rule, Cauchy–Schwarz, and change of variables</span><span class=\"detail-action\"><i>Show</i><i>Hide</i></span></summary>\n            <div class=\"detail-content r2-derivation-stack\">\n              <div class=\"derivation-step-label\"><span>1</span><strong>Follow η along the mesh trajectory.</strong></div>\n              <p>Along Y(t;x,t<sup>n</sup>), the chain rule converts an ordinary derivative of the composition into the mesh material derivative:</p>\n              <div class=\"formula-display formula-compact html-math\"><span class=\"frac\"><span class=\"top\">d</span><span class=\"bottom\">dt</span></span> η(Y(t;x,t<sup>n</sup>),t) = <span class=\"mdot\">η</span>(Y(t;x,t<sup>n</sup>),t).</div>\n              <div class=\"formula-display formula-compact html-math\">Q<sub>mov</sub><sup>n</sup>(x) = <span class=\"frac\"><span class=\"top\">1</span><span class=\"bottom\">Δt</span></span> ∫<sub>t<sup>n-1</sup></sub><sup>t<sup>n</sup></sup> <span class=\"mdot\">η</span>(Y(t;x,t<sup>n</sup>),t) dt.</div>\n              <div class=\"derivation-step-label\"><span>2</span><strong>Apply Cauchy–Schwarz in time.</strong></div>\n              <div class=\"formula-display formula-compact html-math norm-formula\">‖Q<sub>mov</sub><sup>n</sup>‖<sub>L<sup>2</sup>(Ω)</sub> ≤ <span class=\"frac\"><span class=\"top\">1</span><span class=\"bottom\">√Δt</span></span> <span class=\"large-root\">[∫<sub>t<sup>n−1</sup></sub><sup>t<sup>n</sup></sup>∫<sub>Ω</sub>|<span class=\"mdot\">η</span>(Y(t;x,t<sup>n</sup>),t)|<sup>2</sup> dx dt]</span><sup>1/2</sup>.</div>\n              <div class=\"derivation-step-label\"><span>3</span><strong>Return from x to the moving point y=Y(t;x,t<sup>n</sup>).</strong></div>\n              <p>A change of variables and the bounded Jacobian of the mesh flow replace the composed integrand by the ordinary L² norm of <span class=\"html-math\"><span class=\"mdot\">η</span></span>:</p>\n              <div class=\"formula-display formula-compact html-math norm-formula\">‖Q<sub>mov</sub><sup>n</sup>‖<sub>L<sup>2</sup>(Ω)</sub> ≤ <span class=\"frac\"><span class=\"top\">C</span><span class=\"bottom\">√Δt</span></span> ‖<span class=\"mdot\">η</span>‖<sub>L<sup>2</sup>(t<sup>n−1</sup>,t<sup>n</sup>;L<sup>2</sup>(Ω))</sub>.</div>\n              <div class=\"derivation-step-label\"><span>4</span><strong>Sum the one-step estimate over time.</strong></div>\n              <div class=\"formula-display formula-compact html-math norm-formula\">‖Q<sub>mov</sub><sup>n</sup>‖<sub>L<sup>2</sup>(Ω)</sub><sup>2</sup> ≤ <span class=\"frac\"><span class=\"top\">C<sup>2</sup></span><span class=\"bottom\">Δt</span></span> ∫<sub>t<sup>n-1</sup></sub><sup>t<sup>n</sup></sup> ‖<span class=\"mdot\">η</span>‖<sub>L<sup>2</sup>(Ω)</sub><sup>2</sup> dt.</div>\n              <div class=\"formula-display formula-compact html-math norm-formula\">Δt ∑<sub>n</sub> ‖Q<sub>mov</sub><sup>n</sup>‖<sub>L<sup>2</sup>(Ω)</sub><sup>2</sup> ≤ C<sup>2</sup> ‖<span class=\"mdot\">η</span>‖<sub>L<sup>2</sup>(0,T;L<sup>2</sup>(Ω))</sub><sup>2</sup>.</div>\n              <p class=\"formal-note\">So the discrete moving-projection quotient is reduced to a continuous-in-time estimate for the material derivative of η.</p>\n            </div>\n          </details>\n\n          <details class=\"math-detail\">\n            <summary><span><b>Full conservative split</b> · algebra behind Q<sub>mov</sub> + Q<sub>mesh</sub> + Q<sub>phys</sub> + Q<sub>J</sub></span><span class=\"detail-action\"><i>Show</i><i>Hide</i></span></summary>\n            <div class=\"detail-content prose-detail\">\n              <p>Add and subtract η<sup>n−1</sup>∘Y<sub>1</sub><sup>n</sup>, η<sup>n−1</sup>, and η<sup>n−1</sup>∘X<sub>1</sub><sup>n</sup> inside the numerator. The final Jacobian term is required because the actual conservative residual contains (η<sup>n−1</sup>∘X<sub>1</sub><sup>n</sup>)γ<sup>n</sup>, whereas the handwritten transport core omits γ<sup>n</sup> to isolate the characteristic part.</p>\n            </div>\n          </details>\n        </div>\n      </section>",
  "analysis-target": "<section class=\"chapter\" id=\"analysis-target\" data-nav=\"analysis\" data-title=\"Estimate the material derivative\">\n        <div class=\"chapter-inner\">\n          <header class=\"chapter-heading compact-heading\">\n            <div><p class=\"chapter-index\">16 · Error estimates</p><h2>Estimate the moving-projection derivative</h2></div>\n            <p class=\"chapter-statement\">The discrete difficulty has become a continuous-in-time question: can the moving elliptic projection retain its optimal L² order after differentiation along the mesh?</p>\n          </header>\n\n          <div class=\"material-notation-banner\">\n            <span>Notation used below</span>\n            <div class=\"formula-inline\"><span class=\"mdot\">v</span> := ∂<sub>t</sub>v + <b>w</b><sub>h</sub>·∇v</div>\n            <p>The centered dot always means the <button class=\"term-link inline-term\" type=\"button\" data-term=\"material-derivative\">mesh material derivative</button>, not an ordinary partial time derivative.</p>\n          </div>\n\n          <div class=\"analysis-logic-flow\" aria-label=\"Material derivative analysis strategy\">\n            <div><span>discrete residual</span><button class=\"term-link flow-term\" type=\"button\" data-term=\"r2-residual\">R<sub>2</sub><sup>n</sup> · moving-space quotient</button></div><i>→</i>\n            <div><span>mesh-flow part</span><button class=\"term-link flow-term\" type=\"button\" data-term=\"q-mov\">Q<sub>mov</sub><sup>n</sup></button></div><i>→</i>\n            <div class=\"logic-focus\"><span>target norm</span><button class=\"term-link flow-term\" type=\"button\" data-term=\"material-derivative\" aria-label=\"Norm of eta dot\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo>‖</mo><mover accent=\"true\"><mi>η</mi><mo>˙</mo></mover><mo>‖</mo></mrow></math></button></div><i>→</i>\n            <div><span>starting identity</span><button class=\"term-link flow-term\" type=\"button\" data-term=\"projection-orthogonality\">projection orthogonality</button></div>\n          </div>\n\n          <article class=\"formal-panel readable-formal wide-formal orthogonality-start\">\n            <div class=\"formal-label\">Starting point · moving elliptic projection</div>\n            <p>Let Π<sub>h</sub>(t)φ be the boundary-compatible elliptic projection and set η=φ−Π<sub>h</sub>(t)φ. Then</p>\n            <div class=\"projection-start-grid\">\n              <div>\n                <span class=\"small-label\">interior orthogonality</span>\n                <div class=\"math-display medium-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                  <mi>A</mi><mrow><mo>(</mo><mi>η</mi><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mo>=</mo><mn>0</mn><mo>,</mo><mspace width=\"1em\"/><mo>∀</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>∈</mo><msub><mi>V</mi><mrow><mi>h</mi><mo>,</mo><mn>0</mn></mrow></msub><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mi>.</mi>\n                </mrow><annotation encoding=\"application/x-tex\">A(\\eta,\\psi_h)=0\\qquad\\forall\\psi_h\\in V_{h,0}(t).</annotation></semantics></math></div>\n                <button class=\"term-link\" type=\"button\" data-term=\"elliptic-form\">A(·,·) · elliptic bilinear form</button>\n              </div>\n              <div>\n                <span class=\"small-label\">boundary trace</span>\n                <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                  <msub><mi>Π</mi><mi>h</mi></msub><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mi>ϕ</mi><msub><mo>|</mo><mi>Γ</mi></msub><mo>=</mo><msubsup><mi>P</mi><mi>h</mi><mi>Γ</mi></msubsup><mrow><mo>(</mo><mi>ϕ</mi><msub><mo>|</mo><mi>Γ</mi></msub><mo>)</mo></mrow><mi>.</mi>\n                </mrow></semantics></math></div>\n                <button class=\"term-link\" type=\"button\" data-term=\"boundary-l2-projection\">P<sub>h</sub><sup>Γ</sup> · boundary L² projection</button>\n              </div>\n            </div>\n          </article>\n\n          <div class=\"differentiate-step\">\n            <div class=\"differentiate-copy\">\n              <span class=\"section-kicker\">Differentiate along the moving mesh</span>\n              <h3>Transport the test function, then differentiate orthogonality</h3>\n              <p>Choose the extension of ψ<sub>h</sub> with fixed nodal coefficients, so that <strong><span class=\"mdot\">ψ</span><sub>h</sub>=0</strong>. Differentiating A(η,ψ<sub>h</sub>)=0 then produces the material derivative of η together with explicit mesh-deformation terms collected in <button class=\"term-link inline-term\" type=\"button\" data-term=\"b-form\">b(η,ψ<sub>h</sub>)</button>.</p>\n            </div>\n            <div>\n              <div class=\"formula-display formula-medium html-math\">A(<span class=\"mdot\">η</span>, ψ<sub>h</sub>) = b(η, ψ<sub>h</sub>).</div>\n              <button class=\"term-link inline-term\" type=\"button\" data-term=\"b-form\">b(η,ψ<sub>h</sub>) · differentiated orthogonality term</button>\n            </div>\n          </div>\n\n          <article class=\"commutator-decomposition\">\n            <div class=\"commutator-head\"><span>Decompose the material derivative error</span><strong>static projection error + projection–transport commutator</strong></div>\n            <div class=\"formula-display formula-medium html-math\"><span class=\"mdot\">η</span> = σ + ρ<sub>h</sub>, &nbsp; σ := <span class=\"mdot\">φ</span> − Π<sub>h</sub>(t)(<span class=\"mdot\">φ</span>).</div>\n            <div class=\"formula-display formula-medium html-math\">ρ<sub>h</sub> := Π<sub>h</sub>(t)(<span class=\"mdot\">φ</span>) − <span class=\"mdot\">[Π<sub>h</sub>(t)φ]</span> ∈ V<sub>h,0</sub>(t).</div>\n            <p>σ is the standard elliptic-projection error of <span class=\"html-math\"><span class=\"mdot\">φ</span></span>. The new quantity ρ<sub>h</sub> measures the failure of the moving projection to commute with mesh transport.</p>\n          </article>\n\n          <article class=\"extension-result-panel material-result-panel\">\n            <div class=\"extension-result-head\"><span>Extension result</span><strong>material derivative with boundary L² projection</strong></div>\n            <p>Under the elliptic regularity, shape-regularity, fixed-boundary, velocity-regularity, and H² solution assumptions, the extension gives</p>\n            <div class=\"estimate-pairs\">\n              <div>\n                <span>static projection</span>\n                <div class=\"formula-display formula-compact html-math norm-formula\">‖η‖<sub>H<sup>1</sup>(Ω)</sub> ≤ C h ‖φ‖<sub>H<sup>2</sup>(Ω)</sub>, &nbsp; ‖η‖<sub>L<sup>2</sup>(Ω)</sub> ≤ C h<sup>2</sup> ‖φ‖<sub>H<sup>2</sup>(Ω)</sub>.</div>\n              </div>\n              <div>\n                <span>mesh material derivative</span>\n                <div class=\"formula-display formula-compact html-math norm-formula\">‖<span class=\"mdot\">η</span>‖<sub>H<sup>1</sup>(Ω)</sub> ≤ C<sub>w</sub> h \n                (‖<span class=\"mdot\">φ</span>‖<sub>H<sup>2</sup>(Ω)</sub> + ‖φ‖<sub>H<sup>2</sup>(Ω)</sub>),</div>\n                <div class=\"formula-display formula-compact html-math norm-formula\">‖<span class=\"mdot\">η</span>‖<sub>L<sup>2</sup>(Ω)</sub> ≤ C<sub>w</sub> h<sup>2</sup>\n                (‖<span class=\"mdot\">φ</span>‖<sub>H<sup>2</sup>(Ω)</sub> + ‖φ‖<sub>H<sup>2</sup>(Ω)</sub>).</div>\n              </div>\n            </div>\n            <div class=\"key-trace-line\"><button class=\"term-link\" type=\"button\" data-term=\"boundary-l2-projection\">Boundary mechanism</button><span>‖φ−P<sub>h</sub><sup>Γ</sup>φ‖<sub>H<sup>−1/2</sup>(Γ)</sub> ≤ C h<sup>2</sup> ‖φ‖<sub>H<sup>2</sup>(Ω)</sub></span></div>\n          </article>\n\n          <details class=\"math-detail extension-detail\">\n            <summary><span><b>Differentiated orthogonality</b> · deformation matrix M<sub>h</sub> and the equation for ρ<sub>h</sub></span><span class=\"detail-action\"><i>Show</i><i>Hide</i></span></summary>\n            <div class=\"detail-content equation-stack\">\n              <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                <msub><mi>M</mi><mi>h</mi></msub><mo>:=</mo><mrow><mo>(</mo><mi>∇</mi><mo>⋅</mo><msub><mi>𝐰</mi><mi>h</mi></msub><mo>)</mo></mrow><mi>I</mi><mo>−</mo><mrow><mo>(</mo><mi>∇</mi><msub><mi>𝐰</mi><mi>h</mi></msub><mo>+</mo><msup><mrow><mo>(</mo><mi>∇</mi><msub><mi>𝐰</mi><mi>h</mi></msub><mo>)</mo></mrow><mi>T</mi></msup><mo>)</mo></mrow><mi>.</mi>\n              </mrow></semantics></math></div>\n              <div class=\"formula-display formula-compact html-math differentiated-equation\">\n                A(<span class=\"mdot\">η</span>,ψ<sub>h</sub>)\n                + (M<sub>h</sub>∇η,∇ψ<sub>h</sub>)\n                + ((∇·<b>w</b><sub>h</sub>)η,ψ<sub>h</sub>) = 0.\n              </div>\n              <div class=\"math-display compact-math\"><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow>\n                <mi>A</mi><mrow><mo>(</mo><msub><mi>ρ</mi><mi>h</mi></msub><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mo>=</mo><mi>b</mi><mrow><mo>(</mo><mi>η</mi><mo>,</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>)</mo></mrow><mo>,</mo><mspace width=\"1em\"/><mo>∀</mo><msub><mi>ψ</mi><mi>h</mi></msub><mo>∈</mo><msub><mi>V</mi><mrow><mi>h</mi><mo>,</mo><mn>0</mn></mrow></msub><mrow><mo>(</mo><mi>t</mi><mo>)</mo></mrow><mi>,</mi>\n              </mrow></semantics></math></div>\n              <p><button class=\"term-link inline-term\" type=\"button\" data-term=\"b-form\">b(η,ψ<sub>h</sub>)</button> = −(M<sub>h</sub>∇η,∇ψ<sub>h</sub>) − ((∇·w<sub>h</sub>)η,ψ<sub>h</sub>).</p>\n            </div>\n          </details>\n\n          <details class=\"math-detail extension-detail\">\n            <summary><span><b>Assumptions and boundary gain</b> · conditions behind the extension result</span><span class=\"detail-action\"><i>Show</i><i>Hide</i></span></summary>\n            <div class=\"detail-content theorem-assumptions\">\n              <ol>\n                <li>Ω⊂ℝ² is polygonal and satisfies the elliptic H²-regularity property used in the duality argument.</li>\n                <li>{𝒯<sub>h</sub>(t)} is a shape-regular, quasi-uniform family of P1 triangular meshes.</li>\n                <li>The physical boundary is fixed and w<sub>h</sub>=0 on Γ.</li>\n                <li>w∈W<sup>2,∞</sup>(Ω)², w<sub>h</sub> is its P1 finite-element approximation, and ‖w<sub>h</sub>−w‖<sub>W<sup>1,∞</sup></sub>≤Ch‖w‖<sub>W<sup>2,∞</sup></sub>.</li>\n                <li>φ(·,t), <span class=\"html-math\"><span class=\"mdot\">φ</span></span>(·,t) ∈ H²(Ω).</li>\n              </ol>\n              <div class=\"boundary-comparison\">\n                <div><span>Lagrange boundary values</span><strong>H<sup>−1/2</sup>(Γ) error ≲ h<sup>3/2</sup></strong><p>With only H²(Ω) regularity, the direct trace estimate loses one half power of h.</p></div>\n                <div class=\"preferred-boundary\"><span>Boundary L² projection</span><strong>H<sup>−1/2</sup>(Γ) error ≲ h²</strong><p>L²(Γ) orthogonality supplies the additional h<sup>1/2</sup> needed in the duality estimate.</p></div>\n              </div>\n            </div>\n          </details>\n\n          <article class=\"analysis-conclusion\" aria-label=\"Conclusion of the multidimensional error-estimate extension\">\n            <header>\n              <span>Conclusion of the extension result</span>\n              <strong>Mesh motion does not force a loss of one spatial order in the projection material derivative.</strong>\n            </header>\n            <div class=\"r2-return-flow\">\n              <strong>‖<span class=\"mdot\">η</span>‖<sub>L²(Ω)</sub> = O(h²)</strong><i>⇒</i>\n              <strong>Q<sub>mov</sub><sup>n</sup> is O(h²) in the discrete time norm</strong><i>⇒</i>\n              <strong>the genuinely moving-projection part of R<sub>2</sub><sup>n</sup> is controlled optimally</strong>\n            </div>\n            <div class=\"conclusion-boundary\">\n              <span>What remains for the full multidimensional LGMM theorem</span>\n              <p>Complete the discrete bounds for Q<sub>mesh</sub><sup>n</sup>, Q<sub>phys</sub><sup>n</sup>, and Q<sub>J</sub><sup>n</sup>, then combine them with R<sub>3</sub><sup>n</sup> and the standard R<sub>1</sub><sup>n</sup> estimate. The result shown here is the sharp projection–transport component, not yet the full theorem.</p>\n            </div>\n          </article>\n        </div>\n      </section>"
};
